import 'app_locale.dart';

class NomAllah {
  final int number;
  final String arabic;
  final String phonetic;
  final String meaningFr;
  final String meaningEn;
  final String explanationFr;
  final String explanationEn;
  final String bienfaitFr;
  final String bienfaitEn;

  const NomAllah({
    required this.number,
    required this.arabic,
    required this.phonetic,
    required this.meaningFr,
    required this.meaningEn,
    required this.explanationFr,
    required this.explanationEn,
    required this.bienfaitFr,
    required this.bienfaitEn,
  });

  String get meaning => AppLocale().isFrench ? meaningFr : meaningEn;
  String get explanation => AppLocale().isFrench ? explanationFr : explanationEn;
  String get bienfait => AppLocale().isFrench ? bienfaitFr : bienfaitEn;
}

const List<NomAllah> kNomsAllah = [
  NomAllah(number: 1, arabic: 'الرَّحْمَنُ', phonetic: 'Ar-Rahman', meaningFr: 'Le Tout Miséricordieux', meaningEn: 'The Most Merciful', explanationFr: 'Celui qui couvre l\'univers entier de sa miséricorde infinie, qui nourrit et pourvoit à tous les êtres créés. C\'est la miséricorde englobante et générale qui s\'étend avant même le mérite.', explanationEn: 'The One who encompasses the entire universe with infinite mercy, who nourishes and provides for all created beings. It is the encompassing and general mercy that extends even before deserving.', bienfaitFr: 'Celui qui répète ce nom 100 fois le vendredi verra l\'amour et l\'affection se manifester dans son cœur et sa vie.', bienfaitEn: 'Whoever repeats this name 100 times on Friday will find love and affection manifesting in their heart and life.'),
  NomAllah(number: 2, arabic: 'الرَّحِيمُ', phonetic: 'Ar-Rahim', meaningFr: 'Le Très Miséricordieux', meaningEn: 'The Compassionate', explanationFr: 'Celui qui manifeste sa miséricorde particulière envers ses serviteurs repentants et croyants. C\'est la miséricorde spéciale accordée après les actes de désobéissance et de repentance sincère.', explanationEn: 'The One who manifests particular mercy toward His repentant and believing servants. This is the special mercy granted after acts of disobedience and sincere repentance.', bienfaitFr: 'Réciter ce nom avec intention sincère après chaque acte répréhensible attire le pardon et purifie l\'âme du serviteur.', bienfaitEn: 'Reciting this name with sincere intention after any blameworthy act attracts forgiveness and purifies the soul of the servant.'),
  NomAllah(number: 3, arabic: 'الْمَلِكُ', phonetic: 'Al-Malik', meaningFr: 'Le Souverain', meaningEn: 'The King', explanationFr: 'Celui qui règne sur toute création avec une autorité absolue, dont le pouvoir ne peut être contesté et dont la royauté n\'a ni début ni fin. Tout est soumis à son pouvoir et à sa domination.', explanationEn: 'The One who reigns over all creation with absolute authority, whose power cannot be challenged and whose kingdom has no beginning or end. Everything is subject to His power and domination.', bienfaitFr: 'Méditer sur ce nom apaise le cœur des inquiétudes terrestres et renforce la confiance en la justice divine.', bienfaitEn: 'Meditating on this name soothes the heart from worldly worries and strengthens trust in divine justice.'),
  NomAllah(number: 4, arabic: 'الْقُدُّوسُ', phonetic: 'Al-Quddus', meaningFr: 'Le Saint', meaningEn: 'The Holy', explanationFr: 'Celui qui est complètement purifié de tout défaut, imperfection et limitation. Il est au-delà de toute ressemblance avec la création, absolument sacré et transcendant.', explanationEn: 'The One who is completely free from all defects, imperfection, and limitation. He is beyond all resemblance to creation, absolutely sacred and transcendent.', bienfaitFr: 'Celui qui demande la purification spirituelle en répétant ce nom verra son âme s\'élever et ses défauts internes diminuer progressivement.', bienfaitEn: 'Those who ask for spiritual purification while repeating this name will see their soul elevated and internal faults diminish progressively.'),
  NomAllah(number: 5, arabic: 'السَّلَامُ', phonetic: 'As-Salam', meaningFr: 'La Paix', meaningEn: 'The Peace', explanationFr: 'Celui qui est la source de toute paix et sécurité, qui préserve sa création de la destruction et de l\'anéantissement. Il accorde la sécurité à celui qui cherche son refuge.', explanationEn: 'The One who is the source of all peace and security, who preserves His creation from destruction and annihilation. He grants security to those who seek His refuge.', bienfaitFr: 'Celui qui dit ce nom chaque matin trouvera la sécurité et la tranquillité à travers sa journée malgré les perturbations du monde.', bienfaitEn: 'Those who recite this name each morning will find security and tranquility throughout their day despite worldly disturbances.'),
  NomAllah(number: 6, arabic: 'الْمُؤْمِنُ', phonetic: 'Al-Moumen', meaningFr: 'Celui Qui Assure', meaningEn: 'The Grantor of Security', explanationFr: 'Celui qui préserve ses créatures et leurs croyances, qui est témoin de la vérité et confirme les paroles véridiques. Il est la source de confiance et d\'assurance pour les croyants.', explanationEn: 'The One who preserves His creatures and their beliefs, who is a witness to truth and confirms truthful words. He is the source of trust and assurance for believers.', bienfaitFr: 'Réciter ce nom augmente la foi et protège le croyant des doutes et de l\'égarement spirituel.', bienfaitEn: 'Reciting this name increases faith and protects the believer from doubts and spiritual misguidance.'),
  NomAllah(number: 7, arabic: 'الْعَزِيزُ', phonetic: 'Al-Aziz', meaningFr: 'Le Tout-Puissant', meaningEn: 'The Mighty', explanationFr: 'Celui dont la force et la puissance sont irrésistibles, dont personne ne peut vaincre ou surpasser. Son honneur et sa dignité sont absolus et inviolables.', explanationEn: 'The One whose strength and power are irresistible, whom no one can overcome or surpass. His honor and dignity are absolute and inviolable.', bienfaitFr: 'Celui qui invoque ce nom avec sincérité sera aidé face à l\'oppression et trouvera la force de surmonter les obstacles.', bienfaitEn: 'Those who invoke this name with sincerity will be helped against oppression and find the strength to overcome obstacles.'),
  NomAllah(number: 8, arabic: 'الْجَبَّارُ', phonetic: 'Al-Jabbar', meaningFr: 'Le Contraignant', meaningEn: 'The Irresistible Force', explanationFr: 'Celui qui impose sa volonté avec puissance absolue, qui contraint et subjugue toute rébellion. C\'est aussi celui qui répare et restaure ce qui est brisé chez ses serviteurs.', explanationEn: 'The One who enforces His will with absolute power, who constrains and subdues all rebellion. He also repairs and restores what is broken in His servants.', bienfaitFr: 'Méditer sur ce nom inspire l\'humilité devant la volonté divine et apaise la fierté de l\'âme égotiste.', bienfaitEn: 'Meditating on this name inspires humility before divine will and soothes the pride of the ego-driven soul.'),
  NomAllah(number: 9, arabic: 'الْمُتَكَبِّرُ', phonetic: 'Al-Mutakabbir', meaningFr: 'Le Superbe', meaningEn: 'The Majestic', explanationFr: 'Celui qui possède la grandeur suprême et la majesté absolue, qui transcende toute création par son essence. Il est au-delà de toute comparaison et de toute ressemblance.', explanationEn: 'The One who possesses supreme greatness and absolute majesty, who transcends all creation by His essence. He is beyond all comparison and resemblance.', bienfaitFr: 'Réciter ce nom régulièrement purifie le cœur de l\'orgueil et de la vantardise personnelle.', bienfaitEn: 'Regular recitation of this name purifies the heart from pride and personal arrogance.'),
  NomAllah(number: 10, arabic: 'الْخَالِقُ', phonetic: 'Al-Khaliq', meaningFr: 'Le Créateur', meaningEn: 'The Creator', explanationFr: 'Celui qui a créé toute existence du néant et qui continue à créer sans cesse. Il est l\'unique créateur dont aucune création ne partage cette capacité divine.', explanationEn: 'The One who created all existence from nothing and continues to create constantly. He is the unique Creator with whom no creation shares this divine capacity.', bienfaitFr: 'Celui qui médite sur ce nom verra son émerveillement face à la création grandir et son cœur s\'emplir de gratitude.', bienfaitEn: 'Those who meditate on this name will find their wonder at creation growing and their hearts filled with gratitude.'),
  NomAllah(number: 11, arabic: 'الْبَارِئُ', phonetic: 'Al-Bari', meaningFr: 'L\'Inventeur', meaningEn: 'The Inventor', explanationFr: 'Celui qui façonne et invente les créations avec perfection et sagesse. Il donna à chaque créature sa forme et sa nature spécifiques selon un dessein divin.', explanationEn: 'The One who shapes and invents creations with perfection and wisdom. He gives each creature its specific form and nature according to divine design.', bienfaitFr: 'Réciter ce nom aide à accepter sa création et son apparence avec contentement et reconnaissance.', bienfaitEn: 'Reciting this name helps in accepting one\'s creation and appearance with contentment and gratitude.'),
  NomAllah(number: 12, arabic: 'الْمُصَوِّرُ', phonetic: 'Al-Musawwir', meaningFr: 'Le Formateur', meaningEn: 'The Fashioner', explanationFr: 'Celui qui donne la forme et l\'apparence à toutes les créatures avec harmonie et beauté. Il ne cesse de façonner les formes conformément à sa sagesse infinie.', explanationEn: 'The One who gives form and appearance to all creatures with harmony and beauty. He continuously shapes forms according to His infinite wisdom.', bienfaitFr: 'Celui qui invoque ce nom pour demander une amélioration personnelle verra son caractère et son apparence s\'améliorer graduellement.', bienfaitEn: 'Those who invoke this name seeking self-improvement will see their character and appearance improve gradually.'),
  NomAllah(number: 13, arabic: 'الْغَفَّارُ', phonetic: 'Al-Ghaffar', meaningFr: 'Celui Qui Pardonne', meaningEn: 'The All-Forgiving', explanationFr: 'Celui qui efface et pardonne les péchés de ses serviteurs à maintes reprises, malgré leurs transgressions continuelles. Son pardon est vaste comme l\'océan.', explanationEn: 'The One who erases and forgives the sins of His servants repeatedly despite their continuous transgressions. His forgiveness is as vast as the ocean.', bienfaitFr: 'Celui qui se repent sincèrement en invoquant ce nom trouvera la paix de l\'âme et la libération du fardeau de la culpabilité.', bienfaitEn: 'Those who sincerely repent while invoking this name will find peace of soul and liberation from the burden of guilt.'),
  NomAllah(number: 14, arabic: 'الْقَهَّارُ', phonetic: 'Al-Qahhar', meaningFr: 'Le Dominateur', meaningEn: 'The Subduer', explanationFr: 'Celui dont la domination absolue s\'exerce sur toute créature qui ne peut lui résister ou échapper à son pouvoir. Tous sont soumis à sa volonté irrésistible.', explanationEn: 'The One whose absolute dominion extends over all creatures who cannot resist or escape His power. All are subject to His irresistible will.', bienfaitFr: 'Méditer sur ce nom renforce la conscience que toute puissance vient de Dieu et éloigne la dépendance aux causes secondaires.', bienfaitEn: 'Meditating on this name strengthens awareness that all power comes from God and distances one from dependence on secondary causes.'),
  NomAllah(number: 15, arabic: 'الْوَهَّابُ', phonetic: 'Al-Wahhab', meaningFr: 'Celui Qui Donne', meaningEn: 'The Bestower', explanationFr: 'Celui qui donne généreusement sans compter, dont les dons sont innombrables et continus. Il donne à qui il veut sans rétribution ou obligation.', explanationEn: 'The One who gives generously without measure, whose gifts are countless and continuous. He gives to whom He wills without recompense or obligation.', bienfaitFr: 'Celui qui invoque ce nom avec reconnaissance verra les bienfaits et les provisions se multiplier dans sa vie.', bienfaitEn: 'Those who invoke this name with gratitude will see blessings and provisions multiply in their life.'),
  NomAllah(number: 16, arabic: 'الرَّزَّاقُ', phonetic: 'Ar-Razzaq', meaningFr: 'Celui Qui Pourvoit', meaningEn: 'The Provider', explanationFr: 'Celui qui nourrit et pourvoit à la subsistance de toute créature. Il est la source de toute provision et de tout bénéfice dans ce monde et l\'autre.', explanationEn: 'The One who nourishes and provides sustenance for all creatures. He is the source of all provision and benefit in this world and the next.', bienfaitFr: 'Réciter ce nom avec confiance et sincérité attire la subsistance et éloigne la pauvreté et l\'inquiétude matérielle.', bienfaitEn: 'Reciting this name with trust and sincerity attracts provision and removes poverty and material anxiety.'),
  NomAllah(number: 17, arabic: 'الْفَتَّاحُ', phonetic: 'Al-Fattah', meaningFr: 'L\'Ouvreur', meaningEn: 'The Opener', explanationFr: 'Celui qui ouvre les portes du succès, de la connaissance et du pardon. Il tranche entre les créatures en jugement et déverrouille les mystères de l\'existence.', explanationEn: 'The One who opens the doors of success, knowledge, and forgiveness. He judges between creatures and unlocks the mysteries of existence.', bienfaitFr: 'Celui qui récite ce nom en début de jour verra les portes des opportunités et des solutions s\'ouvrir devant lui.', bienfaitEn: 'Those who recite this name at the start of the day will see doors of opportunities and solutions opening before them.'),
  NomAllah(number: 18, arabic: 'الْعَلِيمُ', phonetic: 'Al-Alim', meaningFr: 'L\'Omniscient', meaningEn: 'The All-Knowing', explanationFr: 'Celui dont la science englobe tous les choses, du passé jusqu\'au futur, du visible à l\'invisible. Sa connaissance est absolue et sans limite.', explanationEn: 'The One whose knowledge encompasses all things, from the past to the future, from the visible to the invisible. His knowledge is absolute and without limit.', bienfaitFr: 'Celui qui médite sur ce nom prend conscience que rien ne peut lui être caché de Dieu et cela renforce son intégrité morale.', bienfaitEn: 'Those who meditate on this name become aware that nothing can be hidden from God, strengthening their moral integrity.'),
  NomAllah(number: 19, arabic: 'الْقَابِضُ', phonetic: 'Al-Qabid', meaningFr: 'Celui Qui Restreint', meaningEn: 'The Constrictor', explanationFr: 'Celui qui restreint les provisions et les bienfaits selon sa sagesse, et qui peut retirer ce qu\'il a accordé. Cette restriction peut être un test ou une miséricorde cachée.', explanationEn: 'The One who restricts provisions and blessings according to His wisdom and can withdraw what He has granted. This restriction may be a test or hidden mercy.', bienfaitFr: 'Accepter ce nom avec patience renforce la contentement et protège le cœur de l\'avidité et du désir immodéré.', bienfaitEn: 'Accepting this name with patience strengthens contentment and protects the heart from greed and excessive desire.'),
  NomAllah(number: 20, arabic: 'الْبَاسِطُ', phonetic: 'Al-Basit', meaningFr: 'Celui Qui Étend', meaningEn: 'The Expander', explanationFr: 'Celui qui étend et augmente les provisions et les bienfaits selon sa volonté. Il donne l\'expansion et la largeur à celui qui il veut favori.', explanationEn: 'The One who expands and increases provisions and blessings according to His will. He gives expansion and abundance to whom He chooses to favor.', bienfaitFr: 'Invoquer ce nom attire l\'abundance et l\'aisance matérielle et spirituelle dans la vie du serviteur.', bienfaitEn: 'Invoking this name attracts abundance and ease, both material and spiritual, into the servant\'s life.'),
  NomAllah(number: 21, arabic: 'الْخَافِضُ', phonetic: 'Al-Khafid', meaningFr: 'Celui Qui Abaisse', meaningEn: 'The Abaser', explanationFr: 'Celui qui abaisse l\'orgueilleux et l\'arrogant, qui rabaisse celui qui s\'élève injustement. C\'est aussi celui qui abaisse les rangs des pécheurs impénitents.', explanationEn: 'The One who abases the proud and arrogant, who lowers those who unjustly exalt themselves. He also lowers the ranks of impenitent sinners.', bienfaitFr: 'Celui qui tient ce nom en mémoire verra son orgueil diminuer et son cœur s\'incliner dans l\'humilité devant la divinité.', bienfaitEn: 'Those who keep this name in mind will see their pride diminish and their heart bow in humility before divinity.'),
  NomAllah(number: 22, arabic: 'الرَّافِعُ', phonetic: 'Ar-Rafi', meaningFr: 'Celui Qui Élève', meaningEn: 'The Exalter', explanationFr: 'Celui qui élève le rang des croyants sincères et des obéissants, qui augmente leur dignité et leur honneur. Il élève aussi les âmes vers la perfection spirituelle.', explanationEn: 'The One who raises the rank of sincere believers and the obedient, who increases their dignity and honor. He also elevates souls toward spiritual perfection.', bienfaitFr: 'Méditer sur ce nom inspire le désir d\'amélioration personnelle et d\'ascension spirituelle constante.', bienfaitEn: 'Meditating on this name inspires desire for self-improvement and constant spiritual ascension.'),
  NomAllah(number: 23, arabic: 'الْمُعِزُّ', phonetic: 'Al-Muiz', meaningFr: 'Celui Qui Honore', meaningEn: 'The Bestower of Honor', explanationFr: 'Celui qui confère l\'honneur et la dignité à qui il veut. Son honneur accordé ne peut être diminué par personne d\'autre.', explanationEn: 'The One who grants honor and dignity to whomever He wills. The honor He gives cannot be diminished by anyone else.', bienfaitFr: 'Invoquer ce nom avec sincérité apporte l\'honneur véritable qui ne dépend pas du jugement des hommes.', bienfaitEn: 'Invoking this name with sincerity brings true honor that does not depend on the judgment of people.'),
  NomAllah(number: 24, arabic: 'الْمُذِلُّ', phonetic: 'Al-Mudhill', meaningFr: 'Celui Qui Humilie', meaningEn: 'The Humiliator', explanationFr: 'Celui qui abaisse celui qui devient arrogant et orgueilleux. Son humiliation peut être une correction ou un test pour rectifier la conduite du serviteur.', explanationEn: 'The One who humbles those who become arrogant and proud. His humiliation may be a correction or a test to rectify the servant\'s conduct.', bienfaitFr: 'Accepter ce nom avec sagesse protège du destin des arrogants et maintient l\'humilité du cœur.', bienfaitEn: 'Accepting this name with wisdom protects from the fate of the arrogant and maintains humility of heart.'),
  NomAllah(number: 25, arabic: 'السَّمِيعُ', phonetic: 'As-Sami', meaningFr: 'L\'Audient', meaningEn: 'The All-Hearing', explanationFr: 'Celui qui entend toutes les paroles et les invocations de ses créatures, même chuchotées secrètement. Son ouïe englobe tout et ne manque rien.', explanationEn: 'The One who hears all words and invocations of His creatures, even those whispered in secret. His hearing encompasses everything and misses nothing.', bienfaitFr: 'Celui qui sait que Dieu l\'écoute toujours parlera avec sagesse et purifiera son discours de la médisance.', bienfaitEn: 'Those who know God is always listening will speak with wisdom and purify their speech from backbiting.'),
  NomAllah(number: 26, arabic: 'الْبَصِيرُ', phonetic: 'Al-Basir', meaningFr: 'Le Voyant', meaningEn: 'The All-Seeing', explanationFr: 'Celui qui voit tout ce qui existe, du plus grand au plus petit, du caché au manifeste. Sa vision pénètre toutes les profondeurs et aucun secret ne lui est dissimulé.', explanationEn: 'The One who sees all that exists, from the greatest to the smallest, from the hidden to the manifest. His sight penetrates all depths and no secret is hidden from Him.', bienfaitFr: 'Sachant que Dieu le voit toujours, le serviteur s\'abstiendra de l\'interdit et cultivera les bonnes actions.', bienfaitEn: 'Knowing that God always sees him, the servant will refrain from the forbidden and cultivate good deeds.'),
  NomAllah(number: 27, arabic: 'الْحَكِيمُ', phonetic: 'Al-Hakim', meaningFr: 'Le Sage', meaningEn: 'The All-Wise', explanationFr: 'Celui dont la sagesse est absolue et parfaite en toutes choses. Chacun de ses actes, ses commandements et ses décrets reflètent une sagesse cachée et profonde.', explanationEn: 'The One whose wisdom is absolute and perfect in all things. Each of His acts, commandments, and decrees reflects hidden and profound wisdom.', bienfaitFr: 'Méditer sur ce nom enseigne l\'acceptation des décrets divins même quand la sagesse en est cachée à la raison humaine.', bienfaitEn: 'Meditating on this name teaches acceptance of divine decrees even when their wisdom is hidden from human reason.'),
  NomAllah(number: 28, arabic: 'الْعَظِيمُ', phonetic: 'Al-Azim', meaningFr: 'Le Magnifique', meaningEn: 'The Magnificent', explanationFr: 'Celui dont la grandeur et la magnificence surpassent toute conception. Sa gloire englobe tout et rien ne peut lui être égalé en sublimité.', explanationEn: 'The One whose greatness and magnificence surpass all conception. His glory encompasses everything and nothing can be equal to Him in sublimity.', bienfaitFr: 'Réciter ce nom rend humble et remplit l\'âme d\'une admiration profonde pour la grandeur divine.', bienfaitEn: 'Reciting this name humbles the soul and fills it with profound admiration for divine greatness.'),
  NomAllah(number: 29, arabic: 'الْغَفُورُ', phonetic: 'Al-Ghafur', meaningFr: 'Celui Qui Pardonne', meaningEn: 'The All-Pardoning', explanationFr: 'Celui qui pardonne les péchés malgré leur nombre et leur gravité, et qui voile les fautes de ses serviteurs. Son pardon couvre tout pour celui qui se repent.', explanationEn: 'The One who pardons sins despite their number and severity, and who conceals the faults of His servants. His forgiveness covers all for those who repent.', bienfaitFr: 'Celui qui confesse ses péchés en invoquant ce nom trouvera l\'absolution et la paix intérieure restaurée.', bienfaitEn: 'Those who confess their sins while invoking this name will find absolution and restored inner peace.'),
  NomAllah(number: 30, arabic: 'الشَّكُورُ', phonetic: 'Ash-Shakur', meaningFr: 'Celui Qui Récompense', meaningEn: 'The Appreciative', explanationFr: 'Celui qui reconnaît et récompense généreusement les bonnes actions, même les plus petites. Il multiplie les récompenses et ne permet pas que l\'effort sincère soit perdu.', explanationEn: 'The One who acknowledges and generously rewards good deeds, even the smallest ones. He multiplies rewards and does not allow sincere effort to be lost.', bienfaitFr: 'Celui qui remercie Dieu sincèrement verra ses bienfaits se multiplier et sa gratitude renforcée continuellement.', bienfaitEn: 'Those who thank God sincerely will see their blessings multiply and their gratitude continuously strengthened.'),
  NomAllah(number: 31, arabic: 'الْعَلِيُّ', phonetic: 'Al-Ali', meaningFr: 'Le Très-Haut', meaningEn: 'The Most High', explanationFr: 'Celui qui est au-dessus de toute création tant en essence qu\'en pouvoir et en sagesse. Son élévation est absolue et rien ne s\'égale à sa hauteur.', explanationEn: 'The One who is above all creation in essence, power, and wisdom. His elevation is absolute and nothing can compare to His supremacy.', bienfaitFr: 'Celui qui contemple ce nom reconnaît la limite de sa propre condition et renforce son besoin de proximité avec le divin.', bienfaitEn: 'Those who contemplate this name recognize the limits of their own condition and strengthen their need for closeness with the divine.'),
  NomAllah(number: 32, arabic: 'الْكَبِيرُ', phonetic: 'Al-Kabir', meaningFr: 'Le Grand', meaningEn: 'The Great', explanationFr: 'Celui dont la grandeur est infinie et incommensurable. Toute grandeur créée est insignifiante comparée à la grandeur divine.', explanationEn: 'The One whose greatness is infinite and incomparable. All created greatness is insignificant compared to divine greatness.', bienfaitFr: 'Méditer sur ce nom apaise les soucis terrestres en rappelant que toute difficulté est petite face à la grandeur de Dieu.', bienfaitEn: 'Meditating on this name soothes worldly worries by reminding that all difficulty is small in the face of God\'s greatness.'),
  NomAllah(number: 33, arabic: 'الْحَفِيظُ', phonetic: 'Al-Hafiz', meaningFr: 'Le Préservateur', meaningEn: 'The Preserver', explanationFr: 'Celui qui préserve et garde toute création du changement, de la destruction et de l\'oubli. Il protège ses serviteurs croyants de tous les malheurs.', explanationEn: 'The One who preserves and guards all creation from change, destruction, and oblivion. He protects His believing servants from all harm.', bienfaitFr: 'Celui qui confie ses affaires à ce nom sera protégé et préservé de tout mal par la grâce divine.', bienfaitEn: 'Those who entrust their affairs to this name will be protected and preserved from all harm by divine grace.'),
  NomAllah(number: 34, arabic: 'الْمُقِيتُ', phonetic: 'Al-Muqit', meaningFr: 'Celui Qui Nourrit', meaningEn: 'The Maintainer', explanationFr: 'Celui qui nourrit et soutient toute existence, qui pourvoit aux besoins de chaque créature. Il est la source continue de subsistance et de force.', explanationEn: 'The One who sustains and maintains all existence, who provides for the needs of every creature. He is the continuous source of sustenance and strength.', bienfaitFr: 'Invoquer ce nom attire les provisions suffisantes et renforce la confiance en l\'entretien de Dieu pour le serviteur.', bienfaitEn: 'Invoking this name attracts sufficient provisions and strengthens trust in God\'s maintenance of the servant.'),
  NomAllah(number: 35, arabic: 'الْحَسِيبُ', phonetic: 'Al-Hasib', meaningFr: 'Celui Qui Compte', meaningEn: 'The Reckoner', explanationFr: 'Celui qui compte les actes de ses serviteurs et les connaît en détail, qui sera suffisant le Jour du Jugement. Il suffit comme témoin et comme juge.', explanationEn: 'The One who reckons the deeds of His servants and knows them in detail, who will be sufficient on the Day of Judgment. He is sufficient as witness and judge.', bienfaitFr: 'Celui qui sait que Dieu compte ses actes révèlera son intention en chaque affaire et purifiera ses motivations.', bienfaitEn: 'Those who know God reckons their deeds will reveal their intention in every matter and purify their motivations.'),
  NomAllah(number: 36, arabic: 'الْجَلِيلُ', phonetic: 'Al-Jalil', meaningFr: 'Le Majestueux', meaningEn: 'The Majestic', explanationFr: 'Celui dont la majesté et la splendeur inspirent la crainte révérencielle. Sa majesté transcende toute conception de grandeur créée.', explanationEn: 'The One whose majesty and splendor inspire reverent fear. His majesty transcends all conception of created greatness.', bienfaitFr: 'Contempler ce nom remplit le cœur d\'une crainte respectueuse qui purifie l\'âme de la rébellion.', bienfaitEn: 'Contemplating this name fills the heart with reverent fear that purifies the soul from rebellion.'),
  NomAllah(number: 37, arabic: 'الْكَرِيمُ', phonetic: 'Al-Karim', meaningFr: 'Le Généreux', meaningEn: 'The Generous', explanationFr: 'Celui dont la générosité est infinie et inépuisable, qui donne sans mesure. Sa noblesse et sa magnanimité se manifestent dans chacun de ses bienfaits.', explanationEn: 'The One whose generosity is infinite and inexhaustible, who gives without measure. His nobility and magnanimity manifest in every single blessing.', bienfaitFr: 'Celui qui demande avec sincérité en invoquant ce nom verra la générosité divine s\'accumuler dans sa vie.', bienfaitEn: 'Those who ask sincerely while invoking this name will see divine generosity accumulate in their life.'),
  NomAllah(number: 38, arabic: 'الرَّقِيبُ', phonetic: 'Ar-Raqib', meaningFr: 'Le Surveillant', meaningEn: 'The Watchful', explanationFr: 'Celui qui surveille toutes les créatures et observe tous leurs actes, secrets et manifestes. Rien ne peut lui échapper ou lui être caché.', explanationEn: 'The One who watches all creatures and observes all their deeds, secret and open. Nothing can escape Him or be hidden from Him.', bienfaitFr: 'Sachant qu\'il est observé par Dieu, le serviteur modèrera ses actes et cultivera la sincérité en toutes circonstances.', bienfaitEn: 'Knowing he is observed by God, the servant will moderate his deeds and cultivate sincerity in all circumstances.'),
  NomAllah(number: 39, arabic: 'الْمُجِيبُ', phonetic: 'Al-Mujib', meaningFr: 'Celui Qui Exauce', meaningEn: 'The Responder', explanationFr: 'Celui qui exauce les invocations et les demandes sincères de ses serviteurs. Il écoute et répond à celui qui l\'appelle avec un cœur sincère.', explanationEn: 'The One who answers the invocations and sincere requests of His servants. He listens and responds to those who call upon Him with a sincere heart.', bienfaitFr: 'Celui qui invoque ce nom avec sincérité et confiance verra ses prières exaucées selon ce qui est mieux pour lui.', bienfaitEn: 'Those who invoke this name with sincerity and trust will see their prayers answered according to what is best for them.'),
  NomAllah(number: 40, arabic: 'الْوَاسِعُ', phonetic: 'Al-Wasi', meaningFr: 'L\'Infini', meaningEn: 'The All-Encompassing', explanationFr: 'Celui dont la science, la puissance et la miséricorde englobent tout. Son infini transcende toute limite créée.', explanationEn: 'The One whose knowledge, power, and mercy encompass everything. His infinity transcends all created limits.', bienfaitFr: 'Celui qui médite sur ce nom trouvera la consolation en sachant que l\'aide de Dieu est aussi vaste que ses difficultés.', bienfaitEn: 'Those who meditate on this name will find consolation knowing that God\'s help is as vast as their difficulties.'),
  NomAllah(number: 41, arabic: 'الْحَكِيمُ', phonetic: 'Al-Hakim', meaningFr: 'Le Sage', meaningEn: 'The All-Wise', explanationFr: 'Celui dont la sagesse est absolue dans ses décrets et ses actes. Chaque choix divin reflète une profonde sagesse souvent cachée à la raison humaine.', explanationEn: 'The One whose wisdom is absolute in His decrees and acts. Each divine choice reflects deep wisdom often hidden from human reason.', bienfaitFr: 'Accepter ce nom avec confiance apaise le cœur lors des épreuves en se souvenant que la sagesse divine en transcende les apparences.', bienfaitEn: 'Accepting this name with trust soothes the heart during trials by remembering that divine wisdom transcends their appearance.'),
  NomAllah(number: 42, arabic: 'الْوَدُودُ', phonetic: 'Al-Wadud', meaningFr: 'Celui Qui Aime', meaningEn: 'The Loving', explanationFr: 'Celui dont l\'amour pour ses serviteurs pieux est constant et profond. C\'est aussi celui qui inspire l\'amour et la tendresse entre ses créatures.', explanationEn: 'The One whose love for His pious servants is constant and deep. He is also the One who inspires love and tenderness between His creatures.', bienfaitFr: 'Celui qui invoque ce nom avec un cœur pur attirera l\'amour et l\'affection sincère des gens et de la part de Dieu.', bienfaitEn: 'Those who invoke this name with a pure heart will attract sincere love and affection from people and from God.'),
  NomAllah(number: 43, arabic: 'الْمَجِيدُ', phonetic: 'Al-Majid', meaningFr: 'Le Glorieux', meaningEn: 'The Glorious', explanationFr: 'Celui dont la gloire et l\'honneur sont suprêmes et inviolables. Sa magnificence engendre la gloire de toute création.', explanationEn: 'The One whose glory and honor are supreme and inviolable. His magnificence generates the glory of all creation.', bienfaitFr: 'Réciter ce nom honore le serviteur et élève son statut parmi les créatures tout en lui rappelant que toute gloire émane de Dieu.', bienfaitEn: 'Reciting this name honors the servant and elevates his status among creatures while reminding him that all glory emanates from God.'),
  NomAllah(number: 44, arabic: 'الْبَاعِثُ', phonetic: 'Al-Baes', meaningFr: 'Celui Qui Ressuscite', meaningEn: 'The Resurrector', explanationFr: 'Celui qui ressuscitera tous les hommes le Jour du Jugement Dernier. C\'est aussi celui qui suscite le bien et la guidance chez ses serviteurs.', explanationEn: 'The One who will resurrect all people on the Day of Final Judgment. He is also the One who awakens goodness and guidance in His servants.', bienfaitFr: 'Méditer sur ce nom renforce la foi au Jugement Dernier et encourage l\'action vertueuse pour la vie éternelle.', bienfaitEn: 'Meditating on this name strengthens faith in the Day of Judgment and encourages virtuous action for eternal life.'),
  NomAllah(number: 45, arabic: 'الشَّهِيدُ', phonetic: 'Ash-Shahid', meaningFr: 'Le Témoin', meaningEn: 'The Witness', explanationFr: 'Celui qui est témoin de tous les actes et paroles des créatures. Il sera le témoin suprême le Jour du Jugement contre ou en faveur de chacun.', explanationEn: 'The One who is a witness to all deeds and words of creatures. He will be the supreme witness on the Day of Judgment for or against each person.', bienfaitFr: 'Sachant que Dieu est témoin de ses actes, le serviteur maintiendra l\'intégrité morale en toute circonstance.', bienfaitEn: 'Knowing that God is a witness to his deeds, the servant will maintain moral integrity in all circumstances.'),
  NomAllah(number: 46, arabic: 'الْحَقُّ', phonetic: 'Al-Haq', meaningFr: 'La Vérité', meaningEn: 'The Truth', explanationFr: 'Celui qui est la Vérité absolue et dont toute vérité émane. L\'existence même dépend de sa vérité incontestable.', explanationEn: 'The One who is absolute Truth and from whom all truth emanates. Existence itself depends on His undeniable truth.', bienfaitFr: 'Celui qui recherche la vérité sincèrement sera guidé vers le chemin droit par la guidance de ce nom divin.', bienfaitEn: 'Those who sincerely seek truth will be guided toward the straight path by the guidance of this divine name.'),
  NomAllah(number: 47, arabic: 'الْوَكِيلُ', phonetic: 'Al-Wakil', meaningFr: 'Celui Qui Pourvoit', meaningEn: 'The Trustee', explanationFr: 'Celui sur qui on place sa confiance absolue et à qui on confie ses affaires. Il s\'occupe des intérêts de celui qui se confie à Lui.', explanationEn: 'The One upon whom absolute trust is placed and to whom affairs are entrusted. He takes care of the interests of those who trust in Him.', bienfaitFr: 'Celui qui remet ses affaires entièrement à Dieu en invoquant ce nom trouvera la paix de l\'âme et le succès.', bienfaitEn: 'Those who fully entrust their affairs to God while invoking this name will find peace of soul and success.'),
  NomAllah(number: 48, arabic: 'الْقَوِيُّ', phonetic: 'Al-Qawi', meaningFr: 'Le Puissant', meaningEn: 'The Strong', explanationFr: 'Celui dont la force et la puissance sont absolues et irresistibles. Aucune force créée ne peut s\'opposer à sa puissance.', explanationEn: 'The One whose strength and power are absolute and irresistible. No created force can oppose His power.', bienfaitFr: 'Invoquer ce nom renforce le serviteur face aux défis de la vie en lui rappelant qu\'il peut puiser dans la puissance divine.', bienfaitEn: 'Invoking this name strengthens the servant in facing life\'s challenges by reminding him he can draw upon divine strength.'),
  NomAllah(number: 49, arabic: 'الْمَتِينُ', phonetic: 'Al-Matin', meaningFr: 'Le Très-Fort', meaningEn: 'The Unshakeable', explanationFr: 'Celui dont la force est extrêmement ferme et inébranlable. Sa fermeté absolue soutient tout l\'univers sans jamais fléchir.', explanationEn: 'The One whose strength is extremely firm and unshakeable. His absolute firmness sustains the entire universe without ever wavering.', bienfaitFr: 'Celui qui demande la fermeté de conviction en invoquant ce nom renforcera sa foi face aux tentations et aux doutes.', bienfaitEn: 'Those who ask for firmness of conviction while invoking this name will strengthen their faith against temptations and doubts.'),
  NomAllah(number: 50, arabic: 'الْوَلِيُّ', phonetic: 'Al-Wali', meaningFr: 'Le Protecteur', meaningEn: 'The Protector', explanationFr: 'Celui qui protège et soutient ses croyants, qui est leur allié et leur auxiliaire. Il est plus proche du serviteur que lui-même.', explanationEn: 'The One who protects and supports His believers, who is their ally and helper. He is closer to the servant than himself.', bienfaitFr: 'Celui qui prend ce nom pour protecteur sera gardé de tout mal et trouvera l\'assistance divine dans les moments critiques.', bienfaitEn: 'Those who take this name as their protector will be guarded from all harm and find divine assistance in critical moments.'),
  NomAllah(number: 51, arabic: 'الْحَمِيدُ', phonetic: 'Al-Hamid', meaningFr: 'Le Louangé', meaningEn: 'The Praiseworthy', explanationFr: 'Celui qui est digne de louanges absolues et perpétuelles malgré la présence ou l\'absence de créatures pour le louer. Toute existence le loue.', explanationEn: 'The One who is worthy of absolute and perpetual praise regardless of whether creatures praise Him or not. All existence praises Him.', bienfaitFr: 'Celui qui loue ce nom régulièrement verra la gratitude se multiplier dans son cœur et embellira sa relation avec le créateur.', bienfaitEn: 'Those who regularly praise this name will see gratitude multiply in their heart and beautify their relationship with the Creator.'),
  NomAllah(number: 52, arabic: 'الْمُحْصِي', phonetic: 'Al-Muhsi', meaningFr: 'Celui Qui Compte', meaningEn: 'The Enumerator', explanationFr: 'Celui qui dénombre tous les éléments créés, du grain de sable à l\'étoile. Chaque créature est connue par Lui en nombre et en détail.', explanationEn: 'The One who numbers all created elements, from the grain of sand to the star. Every creature is known to Him in number and detail.', bienfaitFr: 'Ce nom rappelle que rien ne s\'échappe au compte de Dieu, inspirant la conscience morale et l\'honnêteté.', bienfaitEn: 'This name reminds us that nothing escapes God\'s reckoning, inspiring moral conscience and honesty.'),
  NomAllah(number: 53, arabic: 'الْمُبْدِئُ', phonetic: 'Al-Mubdi', meaningFr: 'Celui Qui Crée Initialement', meaningEn: 'The Originator', explanationFr: 'Celui qui crée les choses la première fois en les amenant du néant à l\'existence. C\'est le début de toute création.', explanationEn: 'The One who creates things for the first time, bringing them from non-existence to existence. This is the origin of all creation.', bienfaitFr: 'Méditer sur ce nom inspire l\'émerveillement devant la création originelle et renforce la confiance en la puissance créatrice.', bienfaitEn: 'Meditating on this name inspires wonder at original creation and strengthens trust in the creating power.'),
  NomAllah(number: 54, arabic: 'الْمُعِيدُ', phonetic: 'Al-Mueed', meaningFr: 'Celui Qui Restaure', meaningEn: 'The Restorer', explanationFr: 'Celui qui ramène les choses à l\'existence après leur destruction ou mort. Il renouvelle et restaure continuellement la création.', explanationEn: 'The One who brings things back to existence after their destruction or death. He continuously renews and restores creation.', bienfaitFr: 'Invoquer ce nom apaise les craintes de la mort en se souvenant que la résurrection est aussi certainement possible que la création.', bienfaitEn: 'Invoking this name soothes fears of death by remembering that resurrection is as surely possible as creation.'),
  NomAllah(number: 55, arabic: 'الْمُحْيِي', phonetic: 'Al-Muhyi', meaningFr: 'Celui Qui Vivifie', meaningEn: 'The Giver of Life', explanationFr: 'Celui qui donne la vie à la matière inerte et qui vivifie l\'âme par la foi et la guidance. Il est source de vie éternelle.', explanationEn: 'The One who gives life to lifeless matter and vivifies the soul through faith and guidance. He is the source of eternal life.', bienfaitFr: 'Celui qui demande la vivification du cœur en invoquant ce nom verra sa vie spirituelle s\'enrichir et son énergie se renouveler.', bienfaitEn: 'Those who ask for the vivification of their heart while invoking this name will see their spiritual life enriched and their energy renewed.'),
  NomAllah(number: 56, arabic: 'الْمُمِيتُ', phonetic: 'Al-Mumit', meaningFr: 'Celui Qui Cause la Mort', meaningEn: 'The Giver of Death', explanationFr: 'Celui qui ôte la vie et cause la mort de toute créature vivante. La mort n\'existe que par sa volonté et son pouvoir.', explanationEn: 'The One who takes away life and causes the death of every living creature. Death exists only through His will and power.', bienfaitFr: 'Accepter ce nom avec sagesse apaise la peur de la mort en la reconnaissant comme une transition vers une autre existence.', bienfaitEn: 'Accepting this name with wisdom soothes fear of death by recognizing it as a transition to another existence.'),
  NomAllah(number: 57, arabic: 'الْحَيُّ', phonetic: 'Al-Hayy', meaningFr: 'Le Vivant', meaningEn: 'The Ever-Living', explanationFr: 'Celui qui possède la vie éternelle en lui-même sans dépendre d\'une source externe. Sa vie est absolue et inépuisable.', explanationEn: 'The One who possesses eternal life within Himself without depending on an external source. His life is absolute and inexhaustible.', bienfaitFr: 'Réciter ce nom purifie le cœur en le connectant à la source éternelle de vie et en libérant la peur de l\'extinction.', bienfaitEn: 'Reciting this name purifies the heart by connecting it to the eternal source of life and freeing it from fear of extinction.'),
  NomAllah(number: 58, arabic: 'الْقَيُّومُ', phonetic: 'Al-Qayyum', meaningFr: 'L\'Autosuffisant', meaningEn: 'The Self-Subsisting', explanationFr: 'Celui qui subsiste par lui-même et dont l\'existence dépend uniquement de sa propre essence. Toute autre existence dépend de Lui.', explanationEn: 'The One who subsists by Himself and whose existence depends only on His own essence. All other existence depends on Him.', bienfaitFr: 'Celui qui médite sur ce nom comprendra que toute dépendance créée provient ultimement de Dieu et non des autres.', bienfaitEn: 'Those who meditate on this name will understand that all created dependence ultimately comes from God and not from others.'),
  NomAllah(number: 59, arabic: 'الْوِتْرُ', phonetic: 'Al-Witr', meaningFr: 'L\'Unique', meaningEn: 'The Odd One', explanationFr: 'Celui qui est sans égal et sans pareil, l\'unique en essence, attributs et actions. Il n\'a ni associé ni similaire.', explanationEn: 'The One who is without equal and peerless, unique in essence, attributes, and actions. He has no partner or equivalent.', bienfaitFr: 'Ce nom protège celui qui le récite de la tendance à associer d\'autres à Dieu et renforce l\'unicité divine dans le cœur.', bienfaitEn: 'This name protects those who recite it from the tendency to associate others with God and strengthens divine uniqueness in the heart.'),
  NomAllah(number: 60, arabic: 'الْفَرْدُ', phonetic: 'Al-Fard', meaningFr: 'L\'Unique', meaningEn: 'The Singular', explanationFr: 'Celui qui est seul et isolé dans son pouvoir, sa domination et ses attributs. Nul ne peut le égaler ou le partager dans sa divinité.', explanationEn: 'The One who is alone and isolated in His power, dominion, and attributes. No one can equal or share in His divinity.', bienfaitFr: 'Invoquer ce nom renforce l\'isolement spirituel du serviteur de tout ce qui n\'est pas Dieu et purifie son intention.', bienfaitEn: 'Invoking this name strengthens the servant\'s spiritual detachment from everything other than God and purifies his intention.'),
  NomAllah(number: 61, arabic: 'الصَّمَدُ', phonetic: 'As-Samad', meaningFr: 'L\'Immuable', meaningEn: 'The Eternal', explanationFr: 'Celui qui est sans besoin, autosuffisant et immuable. Tous ont besoin de Lui mais Lui n\'a besoin de personne.', explanationEn: 'The One who is in need of nothing, self-sufficient and unchanging. Everyone needs Him but He needs no one.', bienfaitFr: 'Celui qui comprend ce nom découvre la vanité des richesses terrestres et dirige son cœur vers la vraie suffisance en Dieu.', bienfaitEn: 'Those who understand this name discover the vanity of earthly riches and direct their heart toward true sufficiency in God.'),
  NomAllah(number: 62, arabic: 'الْقَادِرُ', phonetic: 'Al-Qadir', meaningFr: 'Le Capable', meaningEn: 'The Able', explanationFr: 'Celui qui possède une puissance absolue sur tous les choses et dont le pouvoir ne connaît aucune limite. Rien ne dépasse sa capacité.', explanationEn: 'The One who possesses absolute power over all things and whose power knows no limit. Nothing surpasses His capacity.', bienfaitFr: 'Celui qui invoque ce nom avec confiance en cas de difficulté verra l\'impossible devenir possible par la grâce divine.', bienfaitEn: 'Those who invoke this name with confidence during hardship will see the impossible become possible through divine grace.'),
  NomAllah(number: 63, arabic: 'الْمُقْتَدِرُ', phonetic: 'Al-Muqtadir', meaningFr: 'Celui Qui a le Pouvoir', meaningEn: 'The All-Powerful', explanationFr: 'Celui qui dispose d\'un pouvoir et d\'une puissance manifeste et complète. Son pouvoir s\'étend sur tout sans nuance ni limitation.', explanationEn: 'The One who possesses evident and complete power and might. His power extends over everything without qualification or limitation.', bienfaitFr: 'Méditer sur ce nom renforce la confiance du serviteur en l\'aide divine et dissipe les doutes concernant sa capacité à surmonter les obstacles.', bienfaitEn: 'Meditating on this name strengthens the servant\'s confidence in divine aid and dispels doubts about his ability to overcome obstacles.'),
  NomAllah(number: 64, arabic: 'الْمُعَجِّلُ', phonetic: 'Al-Mou\'ajjil', meaningFr: 'Celui Qui Accélère', meaningEn: 'The Expediter', explanationFr: 'Celui qui avance et accélère l\'arrivée des choses selon sa sagesse. Il peut accélérer la punition ou la récompense de celui qu\'il veut.', explanationEn: 'The One who brings forward and expedites the arrival of things according to His wisdom. He can hasten punishment or reward for whom He wills.', bienfaitFr: 'Accepter ce nom avec patience apaise l\'inquiétude concernant le moment de l\'arrivée de la provision ou de la récompense.', bienfaitEn: 'Accepting this name with patience soothes anxiety about when provision or reward will arrive.'),
  NomAllah(number: 65, arabic: 'الْمُؤَخِّرُ', phonetic: 'Al-Moakhkhir', meaningFr: 'Celui Qui Retarde', meaningEn: 'The Delayer', explanationFr: 'Celui qui retarde et ajourne les choses selon son plan divin. Il diffère parfois ce qui semble urgent pour une sagesse cachée.', explanationEn: 'The One who delays and postpones things according to His divine plan. He sometimes defers what seems urgent for hidden wisdom.', bienfaitFr: 'Celui qui accepte les retards en invoquant ce nom trouvera la sagesse dans l\'attente et développera la patience vertueuse.', bienfaitEn: 'Those who accept delays while invoking this name will find wisdom in waiting and develop virtuous patience.'),
  NomAllah(number: 66, arabic: 'الْأَوَّلُ', phonetic: 'Al-Awal', meaningFr: 'Le Premier', meaningEn: 'The First', explanationFr: 'Celui qui existe avant tout, sans commencement à son existence. Il est antérieur à toute création.', explanationEn: 'The One who exists before everything, without beginning to His existence. He is prior to all creation.', bienfaitFr: 'Ce nom rappelle que toute chose nouvelle commence après Dieu, ancrant la conscience de la dépendance primordiale.', bienfaitEn: 'This name reminds us that everything new begins after God, anchoring awareness of primordial dependence.'),
  NomAllah(number: 67, arabic: 'الْآخِرُ', phonetic: 'Al-Akhir', meaningFr: 'Le Dernier', meaningEn: 'The Last', explanationFr: 'Celui qui demeurera après la disparition de toute création. Il est la destination finale et la fin de tout.', explanationEn: 'The One who will remain after the disappearance of all creation. He is the final destination and the end of all things.', bienfaitFr: 'Réciter ce nom prépare l\'âme à l\'Au-delà et maintient la conscience que le vrai succès réside dans l\'éternité avec Dieu.', bienfaitEn: 'Reciting this name prepares the soul for the afterlife and maintains awareness that true success lies in eternity with God.'),
  NomAllah(number: 68, arabic: 'الظَّاهِرُ', phonetic: 'Az-Zahir', meaningFr: 'Le Manifeste', meaningEn: 'The Manifest', explanationFr: 'Celui qui est apparent et visible dans ses signes et ses créations, bien que son essence reste transcendante. Son existence et sa puissance sont manifestes.', explanationEn: 'The One who is apparent and visible in His signs and creations, though His essence remains transcendent. His existence and power are manifest.', bienfaitFr: 'Celui qui médite sur ce nom percevra les signes de Dieu dans la création et raffinera son observation spirituelle.', bienfaitEn: 'Those who meditate on this name will perceive the signs of God in creation and refine their spiritual observation.'),
  NomAllah(number: 69, arabic: 'الْبَاطِنُ', phonetic: 'Al-Batin', meaningFr: 'Le Caché', meaningEn: 'The Hidden', explanationFr: 'Celui dont l\'essence est complètement cachée et transcendante, imperceptible aux sens. Il est au-delà de toute compréhension créée.', explanationEn: 'The One whose essence is completely hidden and transcendent, imperceptible to the senses. He is beyond all created understanding.', bienfaitFr: 'Accepter ce nom apaise le cœur en acceptant que les mystères divins dépassent la compréhension humaine.', bienfaitEn: 'Accepting this name soothes the heart by accepting that divine mysteries transcend human understanding.'),
  NomAllah(number: 70, arabic: 'الْوَالِي', phonetic: 'Al-Wali', meaningFr: 'Le Souverain', meaningEn: 'The Sovereign', explanationFr: 'Celui qui gouverne absolument et qui est le maître suprême. Il administre les affaires de l\'univers avec sagesse et justice.', explanationEn: 'The One who governs absolutely and is the supreme master. He administers the affairs of the universe with wisdom and justice.', bienfaitFr: 'Celui qui accepte l\'autorité de ce nom dans sa vie trouvera ordre et justice dans les circonstances apparemment chaotiques.', bienfaitEn: 'Those who accept the authority of this name in their life will find order and justice in seemingly chaotic circumstances.'),
  NomAllah(number: 71, arabic: 'الْمُتَعَالِي', phonetic: 'Al-Mutaali', meaningFr: 'L\'Infiniment Haut', meaningEn: 'The Most High', explanationFr: 'Celui qui transcende absolument toute création par sa hauteur et sa gloire. Il est élevé au-delà de toute comparaison et ressemblance.', explanationEn: 'The One who absolutely transcends all creation by His height and glory. He is exalted beyond all comparison and resemblance.', bienfaitFr: 'Méditer sur ce nom enseigne l\'humilité authentique en reconnaissant l\'immense distance entre la créature et le Créateur.', bienfaitEn: 'Meditating on this name teaches authentic humility by recognizing the immense distance between the creature and the Creator.'),
  NomAllah(number: 72, arabic: 'الْبِرُّ', phonetic: 'Al-Bir', meaningFr: 'La Vertu', meaningEn: 'The Good', explanationFr: 'Celui qui est bon et bienveillant envers sa création, qui manifeste la générosité et la justice. Sa bonté est constante et sans limite.', explanationEn: 'The One who is good and benevolent toward His creation, who manifests generosity and justice. His goodness is constant and limitless.', bienfaitFr: 'Celui qui invoque ce nom avec sincérité développera la compassion envers autrui et la bonté deviendra sa nature.', bienfaitEn: 'Those who invoke this name with sincerity will develop compassion toward others and goodness will become their nature.'),
  NomAllah(number: 73, arabic: 'التَّوَّابُ', phonetic: 'At-Tawwab', meaningFr: 'Celui Qui Pardonne', meaningEn: 'The Pardoning', explanationFr: 'Celui qui accepte le repentir de ses serviteurs et qui les réadmet continuellement dans sa grâce. Son pardon ne s\'épuise jamais.', explanationEn: 'The One who accepts the repentance of His servants and continuously readmits them into His grace. His forgiveness never runs out.', bienfaitFr: 'Celui qui se repent sincèrement en invoquant ce nom trouvera la porte du pardon toujours ouverte à son retour.', bienfaitEn: 'Those who sincerely repent while invoking this name will find the door of forgiveness always open to their return.'),
  NomAllah(number: 74, arabic: 'الْحَفِيظُ', phonetic: 'Al-Hafiz', meaningFr: 'Le Gardien', meaningEn: 'The Guardian', explanationFr: 'Celui qui garde et protège sa création du changement, de l\'oubli et de la destruction. Il préserve tout ce qui existe.', explanationEn: 'The One who guards and protects His creation from change, oblivion, and destruction. He preserves all that exists.', bienfaitFr: 'Celui qui place sa confiance en ce nom verra ses affaires protégées et ses intérêts préservés par le gardien divin.', bienfaitEn: 'Those who place their trust in this name will see their affairs protected and their interests preserved by the divine guardian.'),
  NomAllah(number: 75, arabic: 'الْعَالِي', phonetic: 'Al-Ali', meaningFr: 'Le Sublime', meaningEn: 'The Sublime', explanationFr: 'Celui qui est suprêmement élevé en essence, en attributs et en actions. Toute élévation créée lui est soumise et inférieure.', explanationEn: 'The One who is supremely exalted in essence, attributes, and actions. All created elevation is subject to and inferior to Him.', bienfaitFr: 'Réciter ce nom élève l\'âme vers les réalités spirituelles supérieures et détache du matérialisme terrestre.', bienfaitEn: 'Reciting this name elevates the soul toward higher spiritual realities and detaches from worldly materialism.'),
  NomAllah(number: 76, arabic: 'الْأَكْرَمُ', phonetic: 'Al-Akram', meaningFr: 'Le Plus Noble', meaningEn: 'The Most Generous', explanationFr: 'Celui qui possède la noblesse suprême et la générosité absolue. Sa magnificence transcende toute concept de noblesse créée.', explanationEn: 'The One who possesses supreme nobility and absolute generosity. His magnificence transcends all concepts of created nobility.', bienfaitFr: 'Celui qui demande la noblesse de caractère en invoquant ce nom recevra l\'honneur véritable de l\'intégrité morale.', bienfaitEn: 'Those who ask for nobility of character while invoking this name will receive true honor through moral integrity.'),
  NomAllah(number: 77, arabic: 'اَلرَّقِيب', phonetic: 'Ar-Raqib', meaningFr: 'Le Vigilant', meaningEn: 'The Alert', explanationFr: 'Celui qui surveille constamment et attention toutes ses créatures. Aucune action n\'échappe à sa vigilance constante.', explanationEn: 'The One who watches constantly and attentively all His creatures. No action escapes His constant vigilance.', bienfaitFr: 'Sachant qu\'il est vigilant, le serviteur purifiera ses actions internes et maintiendra l\'intégrité en secret comme en public.', bienfaitEn: 'Knowing He is vigilant, the servant will purify his inner actions and maintain integrity in secret as in public.'),
  NomAllah(number: 78, arabic: 'الْقِيَّام', phonetic: 'Al-Qiyam', meaningFr: 'Celui Qui Gère', meaningEn: 'The Maintainer', explanationFr: 'Celui qui gère et administre les affaires de sa création sans cesse. Il maintient l\'ordre de l\'univers par son gestion sagesse.', explanationEn: 'The One who manages and administers the affairs of His creation continuously. He maintains the order of the universe through wise administration.', bienfaitFr: 'Invoquer ce nom apaise l\'inquiétude en reconnaissant que la gestion de tous les affaires appartient ultimement à Dieu.', bienfaitEn: 'Invoking this name soothes anxiety by recognizing that the management of all affairs ultimately belongs to God.'),
  NomAllah(number: 79, arabic: 'الرَّقِيقُ', phonetic: 'Ar-Raqiq', meaningFr: 'Le Délicat', meaningEn: 'The Subtle', explanationFr: 'Celui dont la miséricorde est délicate et subtile, qui touche le cœur doucement. Sa bonté couvre les créatures avec une tendresse infinie.', explanationEn: 'The One whose mercy is delicate and subtle, who touches the heart gently. His goodness covers creatures with infinite tenderness.', bienfaitFr: 'Méditer sur ce nom apaise le cœur blessé en le remplissant de la tendresse infinie de la miséricorde divine.', bienfaitEn: 'Meditating on this name soothes the wounded heart by filling it with the infinite tenderness of divine mercy.'),
  NomAllah(number: 80, arabic: 'الْقَدِيرُ', phonetic: 'Al-Qadir', meaningFr: 'Le Puissant', meaningEn: 'The Powerful', explanationFr: 'Celui qui possède le pouvoir absolu et qui peut accomplir toute chose. Aucune difficulté ne peut le dépasser.', explanationEn: 'The One who possesses absolute power and can accomplish all things. No difficulty can surpass Him.', bienfaitFr: 'Celui qui se tourne vers ce nom en cas de difficulté trouvera la force et la capacité de surmonter n\'importe quel obstacle.', bienfaitEn: 'Those who turn to this name in difficulty will find the strength and ability to overcome any obstacle.'),
  NomAllah(number: 81, arabic: 'السِّتِّيرُ', phonetic: 'As-Sittir', meaningFr: 'Celui Qui Voile', meaningEn: 'The Concealer', explanationFr: 'Celui qui voile les fautes de ses serviteurs et ne les expose pas publiquement. Il couvre avec miséricorde les défauts de ses créatures.', explanationEn: 'The One who conceals the faults of His servants and does not expose them publicly. He covers with mercy the defects of His creatures.', bienfaitFr: 'Celui qui garde les secrets des autres et voile leurs défauts recevra le voilement divin sur ses propres fautes.', bienfaitEn: 'Those who keep the secrets of others and conceal their faults will receive divine concealment of their own faults.'),
  NomAllah(number: 82, arabic: 'الْعَفُوُّ', phonetic: 'Al-Afu', meaningFr: 'Celui Qui Pardonne', meaningEn: 'The Pardoner', explanationFr: 'Celui qui pardonne largement et efface les péchés entièrement, qui annule le châtiment mérité. Son pardon est complet.', explanationEn: 'The One who forgives widely and erases sins completely, who cancels deserved punishment. His forgiveness is complete.', bienfaitFr: 'Celui qui pardonne sincèrement aux autres en invoquant ce nom recevra le pardon complet de ses propres erreurs.', bienfaitEn: 'Those who sincerely forgive others while invoking this name will receive complete forgiveness of their own mistakes.'),
  NomAllah(number: 83, arabic: 'الرَّؤُوفُ', phonetic: 'Ar-Rauf', meaningFr: 'Celui Qui est Doux', meaningEn: 'The Clement', explanationFr: 'Celui qui manifeste une douceur et une tendresse extrêmes dans sa miséricorde. Son traitement est plein de compassion délicate.', explanationEn: 'The One who manifests extreme gentleness and tenderness in His mercy. His treatment is full of delicate compassion.', bienfaitFr: 'Celui qui se repent en invoquant ce nom trouvera Dieu doux et compatissant envers ses défauts et son faiblesses.', bienfaitEn: 'Those who repent while invoking this name will find God gentle and compassionate toward their faults and weaknesses.'),
  NomAllah(number: 84, arabic: 'مَالِكُ الْمُلْكِ', phonetic: 'Malik-ul-Mulk', meaningFr: 'Le Maître du Domaine', meaningEn: 'The Master of the Kingdom', explanationFr: 'Celui qui possède la royauté et la domination absolues. Tout pouvoir créé est un emprunt temporaire de sa royauté éternelle.', explanationEn: 'The One who possesses absolute kingdom and dominion. All created power is a temporary loan from His eternal kingdom.', bienfaitFr: 'Méditer sur ce nom purifie le cœur de l\'attachement aux pouvoirs terrestres temporels et oriente vers l\'éternel.', bienfaitEn: 'Meditating on this name purifies the heart from attachment to temporal earthly powers and directs toward the eternal.'),
  NomAllah(number: 85, arabic: 'ذُو الْجَلَالِ وَالْإِكْرَامِ', phonetic: 'Dhu-al-Jalal wa-al-Ikram', meaningFr: 'Possesseur de Gloire et d\'Honneur', meaningEn: 'Possessor of Majesty and Honor', explanationFr: 'Celui qui possède une gloire majestueuse et une grandeur honorable. Ses gloire et honneur sont absolus et inviolables.', explanationEn: 'The One who possesses majestic glory and honorable greatness. His glory and honor are absolute and inviolable.', bienfaitFr: 'Réciter ce nom avec révérence renforce le respect divin et élève l\'âme vers la contemplation de la magnificence divine.', bienfaitEn: 'Reciting this name with reverence strengthens divine respect and elevates the soul toward contemplating divine magnificence.'),
  NomAllah(number: 86, arabic: 'الْمُقْسِطُ', phonetic: 'Al-Muqsit', meaningFr: 'Celui Qui Rend Justice', meaningEn: 'The Just', explanationFr: 'Celui qui rend justice avec équité et impartialité à tous ses serviteurs. Sa justice est parfaite et sans favoritisme.', explanationEn: 'The One who renders justice with equity and impartiality to all His servants. His justice is perfect and without favoritism.', bienfaitFr: 'Celui qui demande la justice en invoquant ce nom verra l\'équité triompher même si la tyrannie semble temporairement dominante.', bienfaitEn: 'Those who seek justice while invoking this name will see equity triumph even if tyranny seems temporarily dominant.'),
  NomAllah(number: 87, arabic: 'الجَمِيعُ', phonetic: 'Al-Jami', meaningFr: 'Celui Qui Rassemble', meaningEn: 'The Gatherer', explanationFr: 'Celui qui rassemble toutes choses et rassemble l\'humanité pour le jugement. Il unifie et coordonne l\'ordre de l\'univers.', explanationEn: 'The One who gathers all things and assembles humanity for judgment. He unifies and coordinates the order of the universe.', bienfaitFr: 'Invoquer ce nom attire l\'unité et la cohésion dans les affaires fragmentées et dispersées du serviteur.', bienfaitEn: 'Invoking this name attracts unity and cohesion in the fragmented and scattered affairs of the servant.'),
  NomAllah(number: 88, arabic: 'الْغَنِيُّ', phonetic: 'Al-Ghani', meaningFr: 'Le Riche', meaningEn: 'The Rich', explanationFr: 'Celui qui est complètement exempt du besoin et qui est autosuffisant absolument. Sa richesse infinie contraste avec la pauvreté créée.', explanationEn: 'The One who is completely free from need and absolutely self-sufficient. His infinite wealth contrasts with created poverty.', bienfaitFr: 'Celui qui médite sur ce nom comprendra la véritable pauvreté de la création et se libèrera de l\'avidité matérielle.', bienfaitEn: 'Those who meditate on this name will understand the true poverty of creation and free themselves from material greed.'),
  NomAllah(number: 89, arabic: 'الْمُغْنِي', phonetic: 'Al-Moughni', meaningFr: 'Celui Qui Enrichit', meaningEn: 'The Enricher', explanationFr: 'Celui qui enrichit ses serviteurs et pourvoit à leur suffisance. Il est la source de toute abondance créée.', explanationEn: 'The One who enriches His servants and provides for their sufficiency. He is the source of all created abundance.', bienfaitFr: 'Celui qui invoque ce nom régulièrement avec gratitude attirera l\'enrichissement spirituel et matériel dans sa vie.', bienfaitEn: 'Those who regularly invoke this name with gratitude will attract spiritual and material enrichment into their life.'),
  NomAllah(number: 90, arabic: 'الْمَانِعُ', phonetic: 'Al-Mani', meaningFr: 'Celui Qui Refuse', meaningEn: 'The Withholder', explanationFr: 'Celui qui retient et refuse ses faveurs selon sa sagesse. Il peut empêcher le mal d\'atteindre ses serviteurs.', explanationEn: 'The One who withholds and refuses His favors according to His wisdom. He can prevent harm from reaching His servants.', bienfaitFr: 'Accepter ce nom apaise le cœur en sachant que tout refus ou privation peut contenir une protection divine.', bienfaitEn: 'Accepting this name soothes the heart knowing that any refusal or deprivation may contain divine protection.'),
  NomAllah(number: 91, arabic: 'الضَّارُّ', phonetic: 'Ad-Dar', meaningFr: 'Celui Qui Nuit', meaningEn: 'The Harmer', explanationFr: 'Celui qui cause le dommage et la souffrance selon sa sagesse et sa justice. Tout mal vient de lui selon le décret divin.', explanationEn: 'The One who causes harm and suffering according to His wisdom and justice. All harm comes from Him according to divine decree.', bienfaitFr: 'Celui qui accepte ce nom avec patience et sincérité trouvera dans le dommage apparent une miséricorde cachée et une correction divine.', bienfaitEn: 'Those who accept this name with patience and sincerity will find hidden mercy and divine correction in apparent harm.'),
  NomAllah(number: 92, arabic: 'النَّافِعُ', phonetic: 'An-Nafi', meaningFr: 'Celui Qui Bénéficie', meaningEn: 'The Benefiter', explanationFr: 'Celui qui procure le bénéfice et l\'avantage à qui il veut. Tout bien et profit vient uniquement de sa volonté.', explanationEn: 'The One who bestows benefit and advantage to whom He wills. All good and profit come only from His will.', bienfaitFr: 'Celui qui demande le bénéfice en invoquant ce nom verra les portes du profit et de l\'utilité s\'ouvrir pour lui.', bienfaitEn: 'Those who seek benefit while invoking this name will see doors of profit and utility open for them.'),
  NomAllah(number: 93, arabic: 'النُّورُ', phonetic: 'An-Nur', meaningFr: 'La Lumière', meaningEn: 'The Light', explanationFr: 'Celui qui est la source de toute lumière physique et spirituelle. Sa lumière illumine tous les univers et les esprits.', explanationEn: 'The One who is the source of all physical and spiritual light. His light illuminates all universes and spirits.', bienfaitFr: 'Celui qui demande l\'illumination du cœur en invoquant ce nom trouvera guidance et clarté dans les affaires obscures.', bienfaitEn: 'Those who ask for heart illumination while invoking this name will find guidance and clarity in obscure matters.'),
  NomAllah(number: 94, arabic: 'الْهَادِي', phonetic: 'Al-Hadi', meaningFr: 'Le Guide', meaningEn: 'The Guide', explanationFr: 'Celui qui guide ses créatures vers le chemin droit et vers lui-même. Sa guidance est parfaite et sans erreur.', explanationEn: 'The One who guides His creatures toward the straight path and toward Himself. His guidance is perfect and without error.', bienfaitFr: 'Celui qui demande la guidance sincèrement en invoquant ce nom sera dirigé vers le chemin de la vérité et de la rectitude.', bienfaitEn: 'Those who sincerely seek guidance while invoking this name will be directed toward the path of truth and righteousness.'),
  NomAllah(number: 95, arabic: 'الْبَدِيعُ', phonetic: 'Al-Badi', meaningFr: 'Celui Qui Crée l\'Imprévu', meaningEn: 'The Originator', explanationFr: 'Celui qui crée des choses merveilleuses et sans précédent. Il combine les créations de manière surprenante et originale.', explanationEn: 'The One who creates wondrous and unprecedented things. He combines creations in surprising and original ways.', bienfaitFr: 'Méditer sur ce nom remplit le cœur de l\'émerveillement devant l\'infinie créativité divine et l\'unicité de chaque créature.', bienfaitEn: 'Meditating on this name fills the heart with wonder at infinite divine creativity and the uniqueness of each creature.'),
  NomAllah(number: 96, arabic: 'الْبَاقِي', phonetic: 'Al-Baqi', meaningFr: 'L\'Éternel', meaningEn: 'The Eternal', explanationFr: 'Celui qui demeure et persiste éternellement, tandis que toute création disparaît. Son existence éternelle transcende le temps.', explanationEn: 'The One who endures and persists eternally, while all creation perishes. His eternal existence transcends time.', bienfaitFr: 'Réciter ce nom prépare le cœur à l\'éternité en rappelant que seule la permanence divine mérite l\'attachement véritable.', bienfaitEn: 'Reciting this name prepares the heart for eternity by reminding that only divine permanence deserves true attachment.'),
  NomAllah(number: 97, arabic: 'الْوَارِثُ', phonetic: 'Al-Warith', meaningFr: 'L\'Héritier', meaningEn: 'The Inheritor', explanationFr: 'Celui qui héritera de toute création après sa fin. À la fin, seul il demeurera éternel après la destruction de tout.', explanationEn: 'The One who will inherit all creation after its end. In the end, only He will remain eternal after the destruction of everything.', bienfaitFr: 'Celui qui comprend ce nom renonce à l\'attachement aux biens terrestres sachant que l\'héritage final appartient à Dieu seul.', bienfaitEn: 'Those who understand this name will renounce attachment to earthly possessions knowing the final inheritance belongs to God alone.'),
  NomAllah(number: 98, arabic: 'الرَّشِيدُ', phonetic: 'Ar-Rashid', meaningFr: 'Celui Qui Conseille', meaningEn: 'The Rightly-Guided', explanationFr: 'Celui qui guide vers la rectitude et le bon conseil divin. Sa guidance est juste et exempte d\'erreur.', explanationEn: 'The One who guides toward rectitude and divine counsel. His guidance is just and free from error.', bienfaitFr: 'Celui qui demande le bon conseil en invoquant ce nom recevra la guidance vers les meilleures décisions et actions.', bienfaitEn: 'Those who seek good counsel while invoking this name will receive guidance toward the best decisions and actions.'),
  NomAllah(number: 99, arabic: 'الصَّبُورُ', phonetic: 'As-Sabur', meaningFr: 'Le Patient', meaningEn: 'The Patient', explanationFr: 'Celui qui tolère les péchés de ses créatures sans se hâter à les châtier. Sa patience infinie permet la repentance et l\'amélioration.', explanationEn: 'The One who tolerates the sins of His creatures without hastening to punish them. His infinite patience allows for repentance and improvement.', bienfaitFr: 'Celui qui demande la patience en invoquant ce nom développera la endurance spirituelle et morale face aux épreuves de la vie.', bienfaitEn: 'Those who ask for patience while invoking this name will develop spiritual and moral endurance in facing life\'s trials.'),
];
